// ========================================
// DEFAULT PORTRAIT URLs
// ========================================
// Provides default AI-generated portrait URLs for race/class combinations.
// These are used as fallbacks when a character doesn't have a custom portrait.
//
// The portrait URLs are loaded from a manifest file that's generated by the
// batch generation script (scripts/generate_default_portraits.py).

(function (global) {
  // Base URL for default portraits on R2
  const DEFAULT_PORTRAITS_BASE = 'https://pub-afa9482f09a14edbab3514fa1466ab95.r2.dev/defaults';
  
  // Manifest will be populated when loaded
  let _manifest = null;
  let _manifestLoading = false;
  let _manifestLoadPromise = null;

  const DefaultPortraits = (global.DefaultPortraits = {
    /**
     * Get the default portrait URL for a race/class combination.
     * Returns null if no default portrait exists for that combo.
     * 
     * @param {string} race - Character race (lowercase, e.g., 'elf', 'half-orc')
     * @param {string} classType - Character class (lowercase, e.g., 'wizard', 'fighter')
     * @returns {string|null} URL to the default portrait, or null if not found
     */
    getUrl(race, classType) {
      if (!race || !classType) return null;
      
      // Normalize inputs
      const normalizedRace = String(race).toLowerCase().trim();
      const normalizedClass = String(classType).toLowerCase().trim();
      const key = `${normalizedRace}-${normalizedClass}`;
      
      // If manifest is loaded, check it first
      if (_manifest && _manifest.portraits && _manifest.portraits[key]) {
        return _manifest.portraits[key].url;
      }
      
      // Fall back to constructed URL (assuming standard naming convention)
      return `${DEFAULT_PORTRAITS_BASE}/${key}.png`;
    },

    /**
     * Check if a default portrait exists for a race/class combination.
     * Note: This only checks if we *expect* a portrait to exist based on the
     * known races and classes. It doesn't verify the URL is accessible.
     * 
     * @param {string} race
     * @param {string} classType
     * @returns {boolean}
     */
    exists(race, classType) {
      if (!race || !classType) return false;
      
      const normalizedRace = String(race).toLowerCase().trim();
      const normalizedClass = String(classType).toLowerCase().trim();
      
      const validRaces = [
        'dwarf', 'elf', 'halfling', 'human', 'dragonborn',
        'gnome', 'half-elf', 'half-orc', 'tiefling'
      ];
      const validClasses = [
        'barbarian', 'bard', 'cleric', 'druid', 'fighter', 'monk',
        'paladin', 'ranger', 'rogue', 'sorcerer', 'warlock', 'wizard'
      ];
      
      return validRaces.includes(normalizedRace) && validClasses.includes(normalizedClass);
    },

    /**
     * Load the manifest file to get exact URLs and metadata.
     * This is optional - getUrl() will work with constructed URLs even
     * without the manifest loaded.
     * 
     * @returns {Promise<Object|null>} The loaded manifest or null on error
     */
    async loadManifest() {
      // Return cached manifest if already loaded
      if (_manifest) return _manifest;
      
      // Return existing promise if already loading
      if (_manifestLoading && _manifestLoadPromise) {
        return _manifestLoadPromise;
      }
      
      _manifestLoading = true;
      _manifestLoadPromise = (async () => {
        try {
          // Try to load from the project root
          const response = await fetch('default-portraits-manifest.json');
          if (!response.ok) {
            console.warn('DefaultPortraits: Could not load manifest, using constructed URLs');
            return null;
          }
          
          _manifest = await response.json();
          console.log(`DefaultPortraits: Loaded manifest with ${Object.keys(_manifest.portraits || {}).length} portraits`);
          return _manifest;
        } catch (e) {
          console.warn('DefaultPortraits: Failed to load manifest:', e);
          return null;
        } finally {
          _manifestLoading = false;
        }
      })();
      
      return _manifestLoadPromise;
    },

    /**
     * Get manifest info (for debugging).
     * @returns {Object|null}
     */
    getManifest() {
      return _manifest;
    },

    /**
     * Check if manifest has been loaded.
     * @returns {boolean}
     */
    isManifestLoaded() {
      return _manifest !== null;
    },

    /**
     * Get all available race/class combinations.
     * @returns {Array<{race: string, class: string, key: string}>}
     */
    getAllCombinations() {
      const races = [
        'dwarf', 'elf', 'halfling', 'human', 'dragonborn',
        'gnome', 'half-elf', 'half-orc', 'tiefling'
      ];
      const classes = [
        'barbarian', 'bard', 'cleric', 'druid', 'fighter', 'monk',
        'paladin', 'ranger', 'rogue', 'sorcerer', 'warlock', 'wizard'
      ];
      
      const combos = [];
      for (const race of races) {
        for (const cls of classes) {
          combos.push({
            race,
            class: cls,
            key: `${race}-${cls}`,
            url: this.getUrl(race, cls)
          });
        }
      }
      return combos;
    }
  });

  // Try to load manifest on script load (non-blocking)
  if (typeof fetch !== 'undefined') {
    DefaultPortraits.loadManifest().catch(() => {
      // Non-fatal - we can still construct URLs
    });
  }
})(window);

